{"content":""""Summarize log severities per date range.

Reads ./reference_date.txt (YYYY-MM-DD) and ./logs/YYYY-MM-DD_<source>.log,
counts ERROR/WARNING/INFO per period, writes ./summary.csv.

Periods (relative to reference date D):
  today          : file date == D
  last_7_days    : D-6 .. D
  last_30_days   : D-29 .. D
  month_to_date  : 1st of D's month .. D
  total          : all files
"""
import csv
import os
import re
import sys
from datetime import date, timedelta

SEVERITIES = ["ERROR", "WARNING", "INFO"]
PERIODS = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
NAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")

BASE = os.path.dirname(os.path.abspath(__file__))
LOGS_DIR = os.path.join(BASE, "logs")
REF_FILE = os.path.join(BASE, "reference_date.txt")
OUT_FILE = os.path.join(BASE, "summary.csv")


def read_reference_date():
    with open(REF_FILE, encoding="utf-8") as fh:
        text = fh.read().strip()
    return date.fromisoformat(text)


def iter_log_files():
    for name in sorted(os.listdir(LOGS_DIR)):
        m = NAME_RE.match(name)
        if not m:
            continue
        yield date.fromisoformat(m.group(1)), os.path.join(LOGS_DIR, name)


def count_file(path):
    counts = {s: 0 for s in SEVERITIES}
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            for sev in SEVERITIES:
                if sev in line:
                    counts[sev] += 1
                    break
    return counts


def main():
    ref = read_reference_date()
    windows = {
        "today": (ref, ref),
        "last_7_days": (ref - timedelta(days=6), ref),
        "last_30_days": (ref - timedelta(days=29), ref),
        "month_to_date": (ref.replace(day=1), ref),
        "total": (date.min, date.max),
    }
    totals = {p: {s: 0 for s in SEVERITIES} for p in PERIODS}

    for fdate, path in iter_log_files():
        counts = count_file(path)
        for period, (lo, hi) in windows.items():
            if lo <= fdate <= hi:
                for sev in SEVERITIES:
                    totals[period][sev] += counts[sev]

    with open(OUT_FILE, "w", encoding="utf-8", newline="") as fh:
        writer = csv.writer(fh)
        writer.writerow(["period", "severity", "count"])
        for period in PERIODS:
            for sev in SEVERITIES:
                writer.writerow([period, sev, totals[period][sev]])

    print("wrote", OUT_FILE, "reference date", ref.isoformat())
    return 0


if __name__ == "__main__":
    sys.exit(main())
